package com.shopsphere;import static org.assertj.core.api.Assertions.assertThat;import java.sql.DriverManager;import org.junit.jupiter.api.Test;import org.testcontainers.containers.MySQLContainer;import org.testcontainers.junit.jupiter.*;
@Testcontainers(disabledWithoutDocker=true)class InventoryPersistenceContainerTest{@Container static MySQLContainer<?>mysql=new MySQLContainer<>("mysql:8.4");@Test void transactionsCommit()throws Exception{try(var c=DriverManager.getConnection(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword());var s=c.createStatement()){c.setAutoCommit(false);s.execute("CREATE TABLE stock_probe(id INT PRIMARY KEY,quantity INT)");s.executeUpdate("INSERT INTO stock_probe VALUES(1,10)");c.commit();var rs=s.executeQuery("SELECT quantity FROM stock_probe WHERE id=1");assertThat(rs.next()).isTrue();assertThat(rs.getInt(1)).isEqualTo(10);}}}
